// Local visual helpers: no network fetch, no dependency or per-frame geometry.
function molBond(THREE, a, b, radius, material) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, a.distanceTo(b), 8), material);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), b.clone().sub(a).normalize());
  return mesh;
}

function molAtomBatches(THREE, KIT, group, atoms, bonds, radius, bondRadius) {
  const colors = {}, byElement = {};
  atoms.forEach((a, i) => (byElement[a.el] ||= []).push(i));
  const dummy = new THREE.Object3D();
  for (const [el, indices] of Object.entries(byElement)) {
    colors[el] = KIT.surface(MOL_ATOM[el] || MOL_ATOM.C, { rough: 0.57, metal: 0 });
    const mesh = new THREE.InstancedMesh(new THREE.SphereGeometry(radius * (el === 'P' ? 1.12 : 1), 12, 8), colors[el], indices.length);
    indices.forEach((index, j) => { dummy.position.copy(atoms[index].p); dummy.updateMatrix(); mesh.setMatrixAt(j, dummy.matrix); });
    group.add(mesh);
  }
  const sticks = new THREE.InstancedMesh(new THREE.CylinderGeometry(bondRadius, bondRadius, 1, 6), KIT.surface(0x9baba9, { rough: 0.66 }), bonds.length);
  const up = new THREE.Vector3(0, 1, 0);
  bonds.forEach(([i, j], k) => {
    const a = atoms[i].p, b = atoms[j].p;
    dummy.position.copy(a).add(b).multiplyScalar(0.5);
    dummy.quaternion.setFromUnitVectors(up, b.clone().sub(a).normalize());
    dummy.scale.set(1, a.distanceTo(b), 1); dummy.updateMatrix(); sticks.setMatrixAt(k, dummy.matrix);
  });
  group.add(sticks);
  group.userData.atomCount = atoms.length; group.userData.bondCount = bonds.length;
}

// Explicit chemical connectivity, not a distance guess. Hydrogens and bond orders
// are omitted in this heavy-atom display. The phosphate ends remain fragments.
function molDnaGraph(rows) {
  const residues = new Map(), bonds = [], hbonds = [];
  rows.forEach((r, i) => { const key = r[0] + ':' + r[1]; if (!residues.has(key)) residues.set(key, { chain: r[0], number: r[1], type: r[2], atoms: {} }); residues.get(key).atoms[r[3]] = i; });
  const sugar = [["P", "OP1"], ["P", "OP2"], ["P", "O5'"], ["O5'", "C5'"], ["C5'", "C4'"], ["C4'", "O4'"], ["O4'", "C1'"], ["C1'", "C2'"], ["C2'", "C3'"], ["C3'", "C4'"], ["C3'", "O3'"]];
  const purine = [['N9','C8'],['C8','N7'],['N7','C5'],['C5','C6'],['C6','N1'],['N1','C2'],['C2','N3'],['N3','C4'],['C4','C5'],['C4','N9']];
  const pyrimidine = [['N1','C2'],['C2','N3'],['N3','C4'],['C4','C5'],['C5','C6'],['C6','N1'],['C2','O2']];
  for (const r of residues.values()) {
    const isPurine = r.type === 'DA' || r.type === 'DG';
    const edges = [...sugar, ...(isPurine ? purine : pyrimidine), ["C1'", isPurine ? 'N9' : 'N1']];
    if (r.type === 'DA') edges.push(['C6','N6']);
    if (r.type === 'DG') edges.push(['C6','O6'],['C2','N2']);
    if (r.type === 'DT') edges.push(['C4','O4'],['C5','C7']);
    if (r.type === 'DC') edges.push(['C4','N4']);
    for (const [a, b] of edges) if (r.atoms[a] !== undefined && r.atoms[b] !== undefined) bonds.push([r.atoms[a], r.atoms[b]]);
    const next = residues.get(r.chain + ':' + (r.number + 1));
    if (next && r.atoms["O3'"] !== undefined && next.atoms.P !== undefined) bonds.push([r.atoms["O3'"], next.atoms.P]);
  }
  // The Dickerson dodecamer is antiparallel: A1 pairs with B24, A6 with B19.
  for (const r of residues.values()) if (r.chain === 'A') {
    const other = residues.get('B:' + (25 - r.number)); if (!other) continue;
    let p = r, q = other;
    if (p.type === 'DT' || p.type === 'DC') [p, q] = [q, p];
    const links = p.type === 'DA' ? [['N6','O4'],['N1','N3']] : [['O6','N4'],['N1','N3'],['N2','O2']];
    links.forEach(([a,b]) => hbonds.push([p.atoms[a], q.atoms[b]]));
  }
  return { residues, bonds, hbonds };
}

function molDashes(THREE, KIT, group, atoms, bonds, radius) {
  const mat = KIT.surface(0x8dbda7, { rough: 0.8 });
  for (const [i, j] of bonds) for (let k = 0; k < 5; k++) {
    const a = atoms[i].p.clone().lerp(atoms[j].p, (k + 0.1) / 5);
    const b = atoms[i].p.clone().lerp(atoms[j].p, (k + 0.6) / 5);
    group.add(molBond(THREE, a, b, radius, mat));
  }
}

UNI.register('protein', ({ THREE, KIT, meta }) => {
  const root = KIT.group(), spin = KIT.group(); root.add(spin);
  const source = MOL_STRUCTURES.protein;
  const all = source.chains.flatMap(c => c.ca.map(r => new THREE.Vector3(...r.slice(1))));
  const box = new THREE.Box3().setFromPoints(all), centre = box.getCenter(new THREE.Vector3());
  const factor = 2.5 / Math.max(...box.getSize(new THREE.Vector3()).toArray());
  const point = xyz => new THREE.Vector3(...xyz).sub(centre).multiplyScalar(factor);
  const colors = [0x78a993, 0xba947c, 0x508877, 0x8c6e88], irons = [];
  source.chains.forEach((chain, n) => {
    const group = KIT.group(); spin.add(group);
    group.name = '4HHB-chain-' + chain.id; group.userData.residues = chain.ca.length;
    const points = chain.ca.map(r => point(r.slice(1)));
    // A continuous C-alpha trace: every deposited residue, no invented sheet.
    group.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points), points.length * 5, 0.026, 8, false), KIT.surface(colors[n], { rough: 0.61 })));
    const atoms = chain.heme.map(r => ({ el: r[1], p: point(r.slice(2)) }));
    molAtomBatches(THREE, KIT, group, atoms, chain.bonds, 0.025, 0.011);
    const fe = atoms[chain.heme.findIndex(r => r[0] === 'FE')].p;
    const iron = KIT.sphere(0.047, 20, KIT.surface(MOL_ATOM.Fe, { rough: 0.46, metal: 0.15 }));
    iron.position.copy(fe); group.add(iron); irons.push(iron);
    for (const p of [points[0], points.at(-1)]) { const cap = KIT.sphere(0.032, 12, KIT.surface(colors[n], { rough: 0.65 })); cap.position.copy(p); group.add(cap); }
  });
  spin.rotation.set(0.14, -0.35, 0.08);
  root.userData.structure = { pdb: '4HHB', representation: 'C-alpha trace and heme heavy atoms', chains: 4, residues: 574, hemes: 4, oxygenBound: false };
  const HS = meta.hotspots || {};
  const hotspots = [
    { id:'pro-helix', get:v => v.copy(point(source.chains[0].ca[10].slice(1))).applyMatrix4(spin.matrixWorld), meta:HS.helix },
    { id:'pro-sheet', get:v => v.copy(point(source.chains[1].ca[65].slice(1))).applyMatrix4(spin.matrixWorld), meta:HS.sheet },
    { id:'pro-heme', get:v => irons[0].getWorldPosition(v), meta:HS.heme },
    { id:'pro-active', get:v => irons[2].getWorldPosition(v), meta:HS.active },
  ].filter(h => h.meta);
  function update(dt) { spin.rotation.y += dt * 0.10; }
  return { root, update, hotspots, dispose: () => KIT.dispose(root) };
});

UNI.register('dna', ({ THREE, KIT, meta }) => {
  const root = KIT.group(), spin = KIT.group(); root.add(spin);
  const rows = MOL_STRUCTURES.dna.atoms, graph = molDnaGraph(rows);
  const raw = rows.map(r => new THREE.Vector3(...r.slice(5)));
  const centre = new THREE.Box3().setFromPoints(raw).getCenter(new THREE.Vector3());
  const mean = ids => ids.reduce((v, i) => v.add(raw[i]), new THREE.Vector3()).multiplyScalar(1 / ids.length);
  const terminal = n => [graph.residues.get('A:' + n).atoms["C1'"], graph.residues.get('B:' + (25-n)).atoms["C1'"]];
  const axis = mean(terminal(12)).sub(mean(terminal(1))).normalize();
  const orient = new THREE.Quaternion().setFromUnitVectors(axis, new THREE.Vector3(0, 1, 0));
  const atoms = rows.map((r, i) => ({ el:r[4], p:raw[i].clone().sub(centre).applyQuaternion(orient).multiplyScalar(0.057) }));
  molAtomBatches(THREE, KIT, spin, atoms, graph.bonds, 0.031, 0.012);
  molDashes(THREE, KIT, spin, atoms, graph.hbonds, 0.0045);
  ['A','B'].forEach((chain, ci) => {
    const points = [];
    for (const r of graph.residues.values()) if (r.chain === chain) for (const name of ['P', "O5'", "C5'", "C4'", "C3'", "O3'"]) if (r.atoms[name] !== undefined) points.push(atoms[r.atoms[name]].p);
    spin.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points), points.length * 3, 0.017, 6, false), KIT.surface(ci ? 0xbb9c76 : 0x77a891, { rough:0.63 })));
  });
  spin.rotation.y = -0.25;
  root.userData.structure = { pdb:'1BNA', residues:24, basePairs:12, atoms:atoms.length, bonds:graph.bonds.length, hydrogenBonds:graph.hbonds.length };
  const HS = meta.hotspots || {}, r = graph.residues.get('A:6');
  const hotspots = [
    { id:'dna-helix', get:v => v.set(0.62,0.5,0).applyMatrix4(spin.matrixWorld), meta:HS.helix },
    { id:'dna-basepair', get:v => v.copy(atoms[r.atoms.N1].p).applyMatrix4(spin.matrixWorld), meta:HS.basepair },
    { id:'dna-backbone', get:v => v.copy(atoms[graph.residues.get('B:16').atoms.P].p).applyMatrix4(spin.matrixWorld), meta:HS.backbone },
    { id:'dna-gene', get:v => v.set(-0.5,-0.5,0.25).applyMatrix4(spin.matrixWorld), meta:HS.gene },
  ].filter(h => h.meta);
  function update(dt) { spin.rotation.y += dt * 0.13; }
  return { root, update, hotspots, dispose: () => KIT.dispose(root) };
});

UNI.register('nucleotide', ({ THREE, KIT, meta }) => {
  const root = KIT.group(), spin = KIT.group(); root.add(spin);
  spin.scale.setScalar(0.82); // Fit both complete backbone ends on narrow screens.
  const rows = MOL_STRUCTURES.dna.atoms.filter(r => (r[0] === 'A' && r[1] === 6) || (r[0] === 'B' && r[1] === 19));
  const graph = molDnaGraph(rows), a = graph.residues.get('A:6'), t = graph.residues.get('B:19');
  const raw = rows.map(r => new THREE.Vector3(...r.slice(5)));
  const centre = new THREE.Box3().setFromPoints(raw).getCenter(new THREE.Vector3());
  const x = raw[t.atoms["C1'"]].clone().sub(raw[a.atoms["C1'"]]).normalize();
  const z = raw[a.atoms.C6].clone().sub(raw[a.atoms.N1]).cross(raw[a.atoms.C2].clone().sub(raw[a.atoms.N1])).normalize();
  const y = z.clone().cross(x).normalize(); z.copy(x).cross(y).normalize();
  const frame = new THREE.Matrix4().makeBasis(x,y,z).transpose();
  const atoms = rows.map((r,i) => ({ el:r[4], p:raw[i].clone().sub(centre).applyMatrix4(frame).multiplyScalar(0.16) }));
  molAtomBatches(THREE, KIT, spin, atoms, graph.bonds, 0.075, 0.029);
  molDashes(THREE, KIT, spin, atoms, graph.hbonds, 0.012);
  root.userData.structure = { pdb:'1BNA', residues:['DA A6','DT B19'], atoms:atoms.length, bonds:graph.bonds.length, hydrogenBonds:2, hydrogensOmitted:true };
  const HS = meta.hotspots || {};
  const hot = (id,index,m) => ({id,get:v => v.copy(atoms[index].p).applyMatrix4(spin.matrixWorld),meta:m});
  const hotspots = [hot('nuc-base',a.atoms.C8,HS.base),hot('nuc-sugar',a.atoms["C1'"],HS.sugar),hot('nuc-phos',a.atoms.P,HS.phosphate),hot('nuc-hbond',t.atoms.O4,HS.hbond)].filter(h=>h.meta);
  let clock=0;
  function update(dt) { clock += dt; spin.rotation.y = Math.sin(clock * 0.18) * 0.25; }
  return { root, update, hotspots, dispose: () => KIT.dispose(root) };
});

UNI.register('atom', ({ THREE, KIT, meta }) => {
  const root = KIT.group(), cloud = KIT.group(), nucleus = KIT.group(); root.add(cloud, nucleus);
  const mats = [KIT.surface(0xc4887c,{rough:0.69}),KIT.surface(0x99a7ad,{rough:0.69})];
  for (let i=0;i<12;i++) {
    const a=i*2.3999632297, y=1-2*(i+0.5)/12, r=Math.sqrt(1-y*y);
    const p=KIT.sphere(0.052,16,mats[i%2]); p.position.set(Math.cos(a)*r*0.091,y*0.091,Math.sin(a)*r*0.091); nucleus.add(p);
  }
  // s/p-shaped probability illustrations, not a fitted many-electron wavefunction.
  // Dots are not individual electrons; the carbon-12 nucleus is enlarged.
  function orbital(kind, count, color, seed) {
    const points=new Float32Array(count*3);
    for (let i=0;i<count;i++) {
      const a=KIT.TAU*KIT.hash(i*11+seed), u=2*KIT.hash(i*13+seed+1)-1;
      let r, px, py, pz;
      if (kind === '1s' || kind === '2s') {
        r=kind==='1s' ? 0.38*Math.pow(KIT.hash(i*17+seed+2),0.57) : 0.54+0.55*Math.pow(KIT.hash(i*17+seed+2),0.45);
        const radial=Math.sqrt(1-u*u); px=r*radial*Math.cos(a); py=r*u; pz=r*radial*Math.sin(a);
      } else {
        const sign=i%2 ? 1:-1, along=0.22+1.02*Math.pow(KIT.hash(i*17+seed+2),0.58);
        r=0.42*Math.sin((along-0.10)/1.3*Math.PI)*Math.sqrt(KIT.hash(i*19+seed+3));
        px=r*Math.cos(a); py=sign*along; pz=r*Math.sin(a);
        if(kind==='2px') [px,py]=[py,px];
      }
      points.set([px,py,pz],i*3);
    }
    const p=KIT.points(points,color,0.024,{opacity:kind==='2s'?0.32:0.67});
    p.name='illustrative-'+kind; cloud.add(p);
  }
  orbital('1s',1100,0xc1d3c9,307); orbital('2s',1700,0x708b86,503);
  orbital('2px',1900,0x83baa7,701); orbital('2py',1900,0x849fbc,907);
  cloud.rotation.set(0.25,0.35,0.22);
  root.userData.structure={element:'carbon-12',protons:6,neutrons:6,configuration:'1s2 2s2 2p2',representation:'illustrative probability clouds; enlarged nucleus; no electron trajectories'};
  const HS=meta.hotspots||{};
  const hotspots=[
    {id:'atom-nucleus',get:v=>nucleus.getWorldPosition(v),meta:HS.nucleus},
    {id:'atom-electron',get:v=>v.set(0.7,0.2,0.4).applyMatrix4(cloud.matrixWorld),meta:HS.electron},
    {id:'atom-valence',get:v=>v.set(-0.25,0.95,0.1).applyMatrix4(cloud.matrixWorld),meta:HS.valence},
  ].filter(h=>h.meta);
  return {root,update:()=>{},hotspots,dispose:()=>KIT.dispose(root)};
});
